resources.text:
.glass {
  background: linear-gradient(145deg, var(--ui-hi), transparent 42%), var(--ui-bg);
  border: 1px solid var(--ui-border);
  border-radius: 14px;
  box-shadow: var(--shadow);
}

.signal-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 8px 4px 6px;
  border-radius: 999px;
  border: 1px solid var(--ui-border);
  background: rgba(5, 16, 18, 0.55);
  font-size: 10.5px;
  color: var(--text);
}
